package com.canteenpro.service;
import com.canteenpro.model.User;import org.springframework.stereotype.Service;import java.util.*;import java.util.concurrent.atomic.AtomicLong;
@Service public class UserService {private final Map<Long,User> users=new LinkedHashMap<>();private final AtomicLong seq=new AtomicLong(1);public List<User> all(){return new ArrayList<>(users.values());}public User get(Long id){User u=users.get(id);if(u==null)throw new RuntimeException("User not found");return u;}public User register(User u){if(users.values().stream().anyMatch(x->x.getEmail().equalsIgnoreCase(u.getEmail())))throw new RuntimeException("Email already registered");u.setId(seq.getAndIncrement());users.put(u.getId(),u);return u;}public User login(String email,String password){return users.values().stream().filter(u->u.getEmail().equalsIgnoreCase(email)&&u.getPassword().equals(password)&&u.isActive()).findFirst().orElseThrow(()->new RuntimeException("Invalid credentials"));}public User update(Long id,User u){get(id);u.setId(id);users.put(id,u);return u;}public void delete(Long id){get(id);users.remove(id);}public User toggle(Long id){User u=get(id);u.setActive(!u.isActive());return u;}}